/**
 * AC-2-15 URL Liveness Checker
 *
 * Auto-generated by /rpi:research phase2 AC-2-15
 * Checks all source URLs from landednz_kb_master_COMPLETE_v1.md
 *
 * Usage: npx ts-node scripts/check-ac-2-15-urls.ts
 * Output: rpi/phase2-roadmap-engine/research/AC-2-15-url-report.json
 */

import { readFileSync, writeFileSync } from 'fs'
import { logger } from '../src/shared/logger'

interface UrlCheckResult {
  taskId: string
  taskName: string
  sourceUrl: string
  status: 'success' | 'error' | 'redirect' | 'timeout'
  statusCode?: number
  redirectUrl?: string
  errorMessage?: string
  responseTime: number
}

interface UrlReport {
  checkedAt: string
  totalTasks: number
  totalUrls: number
  summary: {
    success: number
    error: number
    redirect: number
    timeout: number
  }
  results: UrlCheckResult[]
}

async function checkUrl(url: string, taskId: string, taskName: string): Promise<UrlCheckResult> {
  const startTime = Date.now()

  try {
    const response = await fetch(url, {
      method: 'HEAD', // Use HEAD to avoid downloading content
      headers: {
        'User-Agent': 'LandedNZ-URLChecker/1.0'
      },
      signal: AbortSignal.timeout(10000) // 10 second timeout
    })

    const responseTime = Date.now() - startTime

    if (response.status >= 200 && response.status < 300) {
      return {
        taskId,
        taskName,
        sourceUrl: url,
        status: 'success',
        statusCode: response.status,
        responseTime
      }
    } else if (response.status >= 300 && response.status < 400) {
      const redirectUrl = response.headers.get('location')
      return {
        taskId,
        taskName,
        sourceUrl: url,
        status: 'redirect',
        statusCode: response.status,
        redirectUrl: redirectUrl || 'Unknown redirect location',
        responseTime
      }
    } else {
      return {
        taskId,
        taskName,
        sourceUrl: url,
        status: 'error',
        statusCode: response.status,
        errorMessage: `HTTP ${response.status}`,
        responseTime
      }
    }
  } catch (error) {
    const responseTime = Date.now() - startTime

    if (error instanceof Error && error.name === 'TimeoutError') {
      return {
        taskId,
        taskName,
        sourceUrl: url,
        status: 'timeout',
        errorMessage: 'Request timeout after 10 seconds',
        responseTime
      }
    }

    return {
      taskId,
      taskName,
      sourceUrl: url,
      status: 'error',
      errorMessage: error instanceof Error ? error.message : 'Unknown error',
      responseTime
    }
  }
}

function parseKnowledgeBase(): Array<{ taskId: string; taskName: string; sourceUrl: string }> {
  const kbPath = '/Users/ruchira/Development/landednz/landednz_kb_master_COMPLETE_v1.md'

  try {
    const content = readFileSync(kbPath, 'utf-8')
    const tasks: Array<{ taskId: string; taskName: string; sourceUrl: string }> = []

    // Parse T01-T21 tasks and extract source URLs
    const taskBlocks = content.split(/^## (T\d{2})/m).slice(1)

    for (let i = 0; i < taskBlocks.length; i += 2) {
      const taskId = taskBlocks[i]
      const taskContent = taskBlocks[i + 1] || ''

      // Extract task name from first line after task ID
      const nameMatch = taskContent.match(/^[^\n]+/)
      const taskName = nameMatch ? nameMatch[0].trim() : 'Unknown task'

      // Extract primary source URL from SOURCES section
      const sourcesMatch = taskContent.match(/SOURCES:\s*\n([^#]*?)(?=\n#|\n\n|\s*$)/s)
      if (sourcesMatch) {
        const sourcesSection = sourcesMatch[1]
        const urlMatch = sourcesSection.match(/https?:\/\/[^\s\)]+/)
        if (urlMatch) {
          tasks.push({
            taskId,
            taskName,
            sourceUrl: urlMatch[0]
          })
        }
      }
    }

    return tasks
  } catch (error) {
    logger.error({ error, kbPath }, 'Failed to parse knowledge base file')
    throw new Error(`Failed to read knowledge base: ${error instanceof Error ? error.message : 'Unknown error'}`)
  }
}

async function main() {
  logger.info('Starting AC-2-15 URL liveness check')

  try {
    // Parse knowledge base to extract tasks and source URLs
    const tasks = parseKnowledgeBase()
    logger.info({ taskCount: tasks.length }, 'Extracted tasks from knowledge base')

    if (tasks.length === 0) {
      throw new Error('No tasks found in knowledge base')
    }

    // Check each URL sequentially (no parallel to avoid overwhelming servers)
    const results: UrlCheckResult[] = []

    for (const task of tasks) {
      logger.info({ taskId: task.taskId }, `Checking URL for ${task.taskId}`)

      const result = await checkUrl(task.sourceUrl, task.taskId, task.taskName)
      results.push(result)

      // Add small delay between requests to be respectful
      await new Promise(resolve => setTimeout(resolve, 500))
    }

    // Generate summary
    const summary = {
      success: results.filter(r => r.status === 'success').length,
      error: results.filter(r => r.status === 'error').length,
      redirect: results.filter(r => r.status === 'redirect').length,
      timeout: results.filter(r => r.status === 'timeout').length
    }

    // Create report
    const report: UrlReport = {
      checkedAt: new Date().toISOString(),
      totalTasks: tasks.length,
      totalUrls: tasks.length, // One URL per task at MVP
      summary,
      results
    }

    // Write report to file
    const outputPath = 'rpi/phase2-roadmap-engine/research/AC-2-15-url-report.json'
    writeFileSync(outputPath, JSON.stringify(report, null, 2))

    logger.info({
      summary,
      outputPath
    }, 'URL check completed')

    // Log any issues found
    const issues = results.filter(r => r.status !== 'success')
    if (issues.length > 0) {
      logger.warn({ issueCount: issues.length }, 'Issues found with source URLs:')
      issues.forEach(issue => {
        logger.warn({
          taskId: issue.taskId,
          status: issue.status,
          url: issue.sourceUrl,
          error: issue.errorMessage || issue.redirectUrl
        }, `${issue.taskId}: ${issue.status}`)
      })
    }

  } catch (error) {
    logger.error(error, 'URL check failed')
    process.exit(1)
  }
}

main()